package com.salespunch360.mobile.ui.account.inventory
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun InventoryScreen(initialMode:String,padding:PaddingValues,vm:AccountInventoryViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;LaunchedEffect(initialMode){vm.show(initialMode)};val modes=listOf("stock","low-stock","opening","transfers","adjustments","batches","serials","prices");Column(Modifier.fillMaxSize().padding(padding).padding(horizontal=16.dp)){LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){items(modes){m->FilterChip(s.mode==m,{vm.show(m)},{Text(m.replace('-',' ').replaceFirstChar{it.uppercase()})})}};Row{OutlinedTextField(s.query,vm::search,label={Text("Search inventory")},modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};if(s.mode !in listOf("stock","low-stock"))FilledIconButton({vm.create(s.mode)}){Icon(Icons.Default.Add,"New movement")}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Card(colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.errorContainer)){Row(Modifier.padding(12.dp)){Text(it,Modifier.weight(1f));TextButton(vm::load){Text("Retry")}}}};val rows=s.rows.filter{it.toString().contains(s.query,true)};if(!s.loading&&rows.isEmpty())Text("No inventory records found.",Modifier.padding(24.dp));LazyColumn{items(rows){x->InventoryRow(x,s.mode)}}};s.editing?.let{InventoryEditor(it,s.options,s.saving,vm::dismiss,vm::save)}}
@Composable private fun InventoryRow(x:JsonObject,mode:String){val product=x["product"]?.jsonObject;val warehouse=x["warehouse"]?.jsonObject;ListItem(headlineContent={Text(product?.str("name")?.ifBlank{null}?:x.str("batchNumber").ifBlank{x.str("serialNumber").ifBlank{x.str("sourceType")}},fontWeight=FontWeight.Bold)},supportingContent={Text(listOf(warehouse?.str("name"),x.str("movementDate").take(10),x.str("reason")).filterNot{it.isNullOrBlank()}.joinToString(" · "))},trailingContent={Column{Text("Qty ${x.str("quantity")}");if(mode=="stock"||mode=="low-stock")Text("Value ₹${x.str("stockValue")}")}})}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun InventoryEditor(kind:String,options:JsonObject,saving:Boolean,onClose:()->Unit,onSave:(String,JsonObject)->Unit){var warehouse by remember{mutableStateOf("")};var destination by remember{mutableStateOf("")};var product by remember{mutableStateOf("")};var quantity by remember{mutableStateOf("")};var cost by remember{mutableStateOf("0")};var direction by remember{mutableStateOf("IN")};var date by remember{mutableStateOf(java.time.LocalDate.now().toString())};var reason by remember{mutableStateOf("")};var batch by remember{mutableStateOf("")};var serial by remember{mutableStateOf("")};var label by remember{mutableStateOf("")};var priceType by remember{mutableStateOf("RETAIL")};AlertDialog(onDismissRequest=onClose,title={Text(kind.replace('-',' ').replaceFirstChar{it.uppercase()})},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){if(kind in listOf("opening","transfers","adjustments"))item{Picker("${if(kind=="transfers")"Source " else ""}warehouse",warehouse,options.array("warehouses")){warehouse=it}};if(kind=="transfers")item{Picker("Destination warehouse",destination,options.array("warehouses")){destination=it}};item{Picker("Item",product,options.array("products")){product=it}};if(kind in listOf("opening","transfers","adjustments"))item{OutlinedTextField(quantity,{quantity=it},label={Text("Quantity")})};if(kind in listOf("opening","adjustments"))item{OutlinedTextField(cost,{cost=it},label={Text("Unit cost / value")})};if(kind=="adjustments")item{PickerText("Direction",direction,listOf("IN","OUT")){direction=it}};if(kind in listOf("opening","transfers","adjustments"))item{OutlinedTextField(date,{date=it},label={Text("Date (YYYY-MM-DD)")})};if(kind in listOf("transfers","adjustments"))item{OutlinedTextField(reason,{reason=it},label={Text("Reason")})};if(kind in listOf("opening","transfers","adjustments")){item{Picker("Batch (when tracked)",batch,options.array("batches")){batch=it}};item{Picker("Serial (when tracked)",serial,options.array("serials")){serial=it}}};if(kind=="batches")item{OutlinedTextField(label,{label=it},label={Text("Batch number")})};if(kind=="serials")item{OutlinedTextField(label,{label=it},label={Text("Serial number")})};if(kind=="prices"){item{PickerText("Price type",priceType,listOf("RETAIL","WHOLESALE")){priceType=it}};item{OutlinedTextField(cost,{cost=it},label={Text("Rate")})}}}},confirmButton={Button(enabled=!saving&&product.isNotBlank()&&when(kind){"opening","adjustments"->warehouse.isNotBlank()&&quantity.isNotBlank();"transfers"->warehouse.isNotBlank()&&destination.isNotBlank()&&quantity.isNotBlank();"batches","serials"->label.isNotBlank();"prices"->cost.isNotBlank();else->false},onClick={onSave(kind,buildJsonObject{put("productId",product);if(kind=="transfers"){put("sourceWarehouseId",warehouse);put("destinationWarehouseId",destination)}else if(kind in listOf("opening","adjustments"))put("warehouseId",warehouse);if(kind in listOf("opening","transfers","adjustments")){put("quantity",quantity);put("movementDate",date)};if(kind in listOf("opening","adjustments"))put("unitCost",cost);if(kind=="adjustments")put("direction",direction);if(kind in listOf("transfers","adjustments"))put("reason",reason);batch.takeIf{it.isNotBlank()}?.let{put("batchId",it)};serial.takeIf{it.isNotBlank()}?.let{put("serialNumberId",it)};if(kind=="batches")put("batchNumber",label);if(kind=="serials")put("serialNumber",label);if(kind=="prices"){put("priceType",priceType);put("rate",cost)}})}){Text("Confirm on server")}},dismissButton={TextButton(onClose){Text("Cancel")}})}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun Picker(label:String,value:String,values:List<JsonElement>,set:(String)->Unit){var open by remember{mutableStateOf(false)};val selected=values.map{it.jsonObject}.firstOrNull{it.str("id")==value};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(selected?.str("name")?.ifBlank{null}?:selected?.str("batchNumber")?.ifBlank{null}?:selected?.str("serialNumber").orEmpty(),{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{e->val x=e.jsonObject;DropdownMenuItem({Text(x.str("name").ifBlank{x.str("batchNumber").ifBlank{x.str("serialNumber")}})},{set(x.str("id"));open=false})}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun PickerText(label:String,value:String,values:List<String>,set:(String)->Unit){var open by remember{mutableStateOf(false)};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(value,{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{v->DropdownMenuItem({Text(v)},{set(v);open=false})}}}}
